from pkg_c01.models import BucketState

class RateLimiter:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable[[], float]) -> None:
        if capacity <= 0 or refill_per_sec < 0:
            raise ValueError('capacity must be positive and refill non-negative')
        self.capacity = float(capacity)
        self.refill_per_sec = float(refill_per_sec)
        self._clock = clock
        self._buckets: dict[str, BucketState] = {}

    def consume(self, key: str, amount: float = 1.0) -> bool:
        if amount <= 0:
            raise ValueError('amount must be positive')
        now = float(self._clock())
        state = self._buckets.get(key)
        if state is None:
            state = BucketState(tokens=self.capacity, last_refill=now)
            self._buckets[key] = state
        elapsed = max(0.0, now - state.last_refill)
        # BUG: forgets to cap at self.capacity and uses strict '>' instead of '>='
        state.tokens = state.tokens + elapsed * self.refill_per_sec
        state.last_refill = now
        if state.tokens > amount:
            state.tokens -= amount
            return True
        return False

    def reset_bucket(self, key: str) -> None:
        # BUG: leaves stale state instead of deleting key
        if key in self._buckets:
            self._buckets[key].tokens = 0.0

