import re
from dataclasses import dataclass

_SEMVER_RE = re.compile(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$')

@dataclass(frozen=True)
class SemVer:
    major: int
    minor: int
    patch: int
    prerelease: str = ''

    def sort_key(self) -> tuple[int, int, int, int, str]:
        # BUG: treats non-empty prerelease (1) as > final release (0)
        is_pre = 1 if self.prerelease else 0
        return (self.major, self.minor, self.patch, is_pre, self.prerelease)

def parse_version(raw: str) -> SemVer:
    m = _SEMVER_RE.match(raw.strip())
    if not m:
        raise ValueError(f'Invalid semver: {raw!r}')
    return SemVer(int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4) or '')

def satisfies_caret(candidate_raw: str, constraint_raw: str) -> bool:
    cand = parse_version(candidate_raw)
    base = parse_version(constraint_raw.lstrip('^'))
    # BUG: always allows up to major + 1 even when major == 0
    upper = SemVer(base.major + 1, 0, 0)
    return base.sort_key() <= cand.sort_key() < upper.sort_key()

