    major: int
    minor: int
    patch: int
    prerelease: str = ''

    def sort_key(self) -> tuple[int, int, int, int, str]:
        """Order prerelease versions below final releases."""
        is_final = 0 if self.prerelease else 1
        return (self.major, self.minor, self.patch, is_final, self.prerelease)

def parse_version(raw: str) -> SemVer:
