        raise ValueError(f'Invalid semver: {raw!r}')
    return SemVer(int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4) or '')

def satisfies_caret(candidate_raw: str, constraint_raw: str) -> bool:
    """Check caret constraint with major, minor, and patch upper bounds."""
    cand = parse_version(candidate_raw)
    base = parse_version(constraint_raw.lstrip('^'))
    if cand.prerelease and not base.prerelease and (cand.major, cand.minor, cand.patch) != (base.major, base.minor, base.patch):
        return False
    if base.major > 0:
        upper = SemVer(base.major + 1, 0, 0)
    elif base.minor > 0:
        upper = SemVer(0, base.minor + 1, 0)
    else:
        upper = SemVer(0, 0, base.patch + 1)
    return base.sort_key() <= cand.sort_key() < upper.sort_key()

