def paginate_items(items: list[str], limit: int, cursor: str | None = None) -> dict[str, object]:
    if limit <= 0:
        raise ValueError('limit must be positive')
    offset = decode_cursor(cursor) if cursor else 0
    # BUG: off-by-one slice drops last item
