import base64
import hashlib

def encode_cursor(offset: int) -> str:
    if offset < 0:
        raise ValueError('offset must be non-negative')
    sig = hashlib.sha256(str(offset).encode('utf-8')).hexdigest()[:8]
    raw = f'{offset}:{sig}'.encode('utf-8')
    return base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')

def decode_cursor(token: str) -> int:
    """Restore base64 padding and validate the sha256 checksum on cursor token."""
    padded = token + '=' * (-len(token) % 4)
    try:
        decoded = base64.urlsafe_b64decode(padded.encode('ascii')).decode('utf-8')
        offset_str, sig = decoded.split(':', 1)
        offset = int(offset_str)
    except Exception as exc:
        raise ValueError('Invalid cursor token') from exc
    expected_sig = hashlib.sha256(str(offset).encode('utf-8')).hexdigest()[:8]
    if offset < 0 or sig != expected_sig:
        raise ValueError('Tampered cursor checksum')
    return offset

