from pkg_c05.interval import Interval

def merge_intervals(intervals: list[Interval]) -> list[Interval]:
    """Sort intervals and merge overlapping or adjacent intervals."""
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv.start, iv.end))
    merged = [ordered[0]]
    for cur in ordered[1:]:
        prev = merged[-1]
        if cur.start <= prev.end:
            merged[-1] = Interval(prev.start, max(prev.end, cur.end))
        else:
            merged.append(cur)
    return merged

def find_free_slots(busy: list[Interval], window_start: int, window_end: int) -> list[Interval]:
    """Clip busy intervals to window_start and window_end and return free slots."""
    if window_end <= window_start:
        return []
    clipped = [
        Interval(max(window_start, iv.start), min(window_end, iv.end))
        for iv in busy
        if iv.end > window_start and iv.start < window_end
    ]
    merged = merge_intervals(clipped)
    free: list[Interval] = []
    cursor = window_start
    for iv in merged:
        if iv.start > cursor:
            free.append(Interval(cursor, iv.start))
        cursor = max(cursor, iv.end)
    if cursor < window_end:
        free.append(Interval(cursor, window_end))
    return free

