from decimal import Decimal, ROUND_HALF_UP
from typing import Protocol

def _round_cents(val: Decimal) -> Decimal:
    return val.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

class DiscountStrategy(Protocol):
    def apply(self, subtotal: Decimal, item_count: int) -> Decimal: ...

class PercentageDiscount:
    def __init__(self, pct: Decimal) -> None:
        self.pct = Decimal(pct)

    def apply(self, subtotal: Decimal, item_count: int) -> Decimal:
        return _round_cents(subtotal * (Decimal('1') - self.pct / Decimal('100')))

class FixedTierDiscount:
    def __init__(self, min_subtotal: Decimal, amount_off: Decimal) -> None:
        self.min_subtotal = Decimal(min_subtotal)
        self.amount_off = Decimal(amount_off)

    def apply(self, subtotal: Decimal, item_count: int) -> Decimal:
        if subtotal >= self.min_subtotal:
            return _round_cents(max(Decimal('0.00'), subtotal - self.amount_off))
        return _round_cents(subtotal)

class BundleDiscount:
    def __init__(self, min_items: int, pct: Decimal) -> None:
        self.min_items = min_items
        self.pct = Decimal(pct)

    def apply(self, subtotal: Decimal, item_count: int) -> Decimal:
        if item_count >= self.min_items:
            return _round_cents(subtotal * (Decimal('1') - self.pct / Decimal('100')))
        return _round_cents(subtotal)

