from pkg_c07.strategies import BundleDiscount, DiscountStrategy, FixedTierDiscount, PercentageDiscount

STRATEGY_REGISTRY: dict[str, DiscountStrategy] = {
    'SAVE10': PercentageDiscount(Decimal('10')),
    'TIER25': FixedTierDiscount(Decimal('100.00'), Decimal('25.00')),
    'BUNDLE15': BundleDiscount(3, Decimal('15')),
}

def calculate_total(subtotal: Decimal, item_count: int, promo_code: str) -> Decimal:
    strategy = STRATEGY_REGISTRY.get(promo_code)
    if strategy is None:
        raise ValueError(f'Unknown promo_code: {promo_code!r}')
    return strategy.apply(Decimal(subtotal), item_count)

