from pkg_c10.events import Subscription

class EventBus:
    """Wildcard topic EventBus supporting priority descending FIFO publish and unsubscribe."""

    def __init__(self) -> None:
        self._subs: list[Subscription] = []
        self._seq = 0

    def subscribe(self, pattern: str, handler: Callable[[str, dict[str, Any]], None], priority: int = 0) -> int:
        """Register wildcard pattern handler with priority and registration order."""
        self._seq += 1
        self._subs.append(Subscription(self._seq, pattern, priority, self._seq, handler))
        return self._seq

    def unsubscribe(self, sub_id: int) -> bool:
        """Remove matching Subscription by sub_id."""
        for idx, sub in enumerate(self._subs):
            if sub.sub_id == sub_id:
                self._subs.pop(idx)
                return True
        return False

    def publish(self, topic: str, payload: dict[str, Any]) -> int:
        """Match fnmatch pattern and invoke handlers sorted by priority descending and FIFO order."""
        matched = [s for s in self._subs if fnmatch(topic, s.pattern)]
        matched.sort(key=lambda s: (-s.priority, s.order))
        for sub in matched:
            sub.handler(topic, payload)
        return len(matched)

