    return posixpath.normpath(cleaned)

def validate_mutation_cage(target_path: str, allowed_prefixes: list[str]) -> bool:
    """Normalize posix paths, check allowed_prefixes without prefix confusion or traversal, allow .env.example, block .env."""
    norm_target = _norm(target_path)
    if norm_target.startswith('..') or norm_target.startswith('/'):
        return False
    base = norm_target.rsplit('/', 1)[-1].lower()
    if (base == '.env' or base.startswith('.env.')) and base not in _SAFE_ENV_NAMES:
        return False
    for raw_prefix in allowed_prefixes:
        prefix = _norm(raw_prefix).rstrip('/')
        if norm_target == prefix or norm_target.startswith(prefix + '/'):
            return True
    return False

