def parse_duration_ms(raw: str) -> float:
    """Parse ms, s, or m minute duration suffix into milliseconds."""
    s = raw.strip().lower()
    if s.endswith('ms'):
        val = float(s[:-2])
    elif s.endswith('s'):
        val = float(s[:-1]) * 1000.0
    elif s.endswith('m'):
        val = float(s[:-1]) * 60000.0
    else:
        raise ValueError(f'Unsupported duration: {raw!r}')
    if val < 0:
        raise ValueError('Duration must be non-negative')
    return val

