    """Extract markdown table rows into dicts while skipping separator lines."""
    lines = [ln.strip() for ln in markdown.splitlines() if ln.strip().startswith('|')]
    if len(lines) < 3:
        return []
    headers = [c.strip() for c in lines[0].strip('|').split('|')]
